// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLParser;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLQueries;
import org.junit.jupiter.api.Test;

class PackedServiceLexicalCompositionTest {

	@Test
	void nestedServiceBodyAndPrologueSurvivePackedReconstructionWithoutChangingOwnership() {
		Service source = parse("BASE <https://example.org/base/> PREFIX ex: <urn:example:> "
				+ "SELECT ?o WHERE { SERVICE <urn:outer> { SERVICE <urn:inner> { <_:remote> ex:p ?o } } }");
		assertTrue(source.containsBNodeReferenceSyntax());
		assertTrue(source.getReservedBNodeIDs().isEmpty());
		Service restored = roundTrip(source);
		assertEquals(source.getServiceExpressionString(), restored.getServiceExpressionString());
		assertEquals(source.getAskQueryString(), restored.getAskQueryString());
		assertEquals(source.getBaseURI(), restored.getBaseURI());
		assertEquals(source.getPrefixDeclarations(), restored.getPrefixDeclarations());
		SPARQLQueries.initializeServiceReferences(restored);
		assertTrue(restored.getReservedBNodeIDs().isEmpty(), "inner SERVICE retains ownership of remote");
		assertTrue(restored.containsBNodeReferenceSyntax());
	}

	@Test
	void directReferenceMetadataSurvivesPackedReconstructionAndClone() {
		Service source = parse("PREFIX ex: <urn:example:> SELECT ?o WHERE { "
				+ "SERVICE <urn:outer> { <_:remote> ex:p ?o } }");
		assertEquals(Set.of("remote"), source.getReservedBNodeIDs());
		Service restored = roundTrip(source);
		assertTrue(restored.isBNodeReferenceMetadataInitialized());
		assertEquals(source.getReservedBNodeIDs(), restored.getReservedBNodeIDs());
		assertEquals(source.getBNodeReferenceVarNames(), restored.getBNodeReferenceVarNames());
		assertEquals(source.containsBNodeReferenceSyntax(), restored.containsBNodeReferenceSyntax());
		assertEquals(source.getReservedBNodeIDs(), restored.clone().getReservedBNodeIDs());
	}

	@Test
	void ordinaryServiceBodyRemainsOrdinaryAfterPackedReconstruction() {
		Service source = parse("PREFIX ex: <urn:example:> SELECT ?o WHERE { "
				+ "SERVICE SILENT <urn:outer> { <urn:s> ex:p ?o } }");
		Service restored = roundTrip(source);
		SPARQLQueries.initializeServiceReferences(restored);
		assertEquals(source.getAskQueryString(), restored.getAskQueryString());
		assertTrue(restored.isSilent());
		assertFalse(restored.containsBNodeReferenceSyntax());
		assertTrue(restored.getReservedBNodeIDs().isEmpty());
	}

	private static Service roundTrip(Service source) {
		PackedQuery encoded = PackedQueryCodec.encode(source);
		return (Service) PackedPlanMaterializer.materialize(encoded, encoded.rootRelId());
	}

	private static Service parse(String query) {
		var parsed = new SPARQLParser().parseQuery(query, null);
		AtomicReference<Service> result = new AtomicReference<>();
		parsed.getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Service service) {
				result.compareAndSet(null, service);
			}
		});
		assertNotNull(result.get());
		return result.get();
	}
}
